<?php
namespace App\Http\Controllers; use App\Models\TrainingInstructor; use Illuminate\Http\Request;
class TrainingInstructorController extends Controller { public function index(){ $instructors=TrainingInstructor::forCompany(auth()->user()->company_id)->get();return view('training.instructors.index',compact('instructors'));} public function store(Request$r){$d=$r->validate(['name'=>'required|string|max:255','document_type'=>'nullable|string|max:20','document_number'=>'nullable|string|max:40','organization'=>'nullable|string|max:255','profession'=>'nullable|string|max:255','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:40','license_number'=>'nullable|string|max:255','license_expiration_date'=>'nullable|date','notes'=>'nullable|string|max:2000']);TrainingInstructor::create(array_merge($d,['company_id'=>$r->user()->company_id,'is_active'=>true]));return back()->with('success','Instructor registrado.');} }
